"""Prepare accurate product metadata and optimized actual captures; no deployment."""
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,hashlib
ROOT=Path(__file__).resolve().parents[1];VERSION='0.1.0-beta.1';DATE='2026-10-26'
def dump(path,data):path.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
def main():
    web=ROOT/'assets/website';web.mkdir(exist_ok=True)
    views=[]
    for name,caption in [('dark-reading','Write in focus, read alongside.'),('light-reading','A clear light theme for everyday work.'),('find-replace','Find and replace with explicit search options.'),('focus','A quiet view that makes room for your words.')]:
        with Image.open(ROOT/f'assets/screenshots/desktop/{name}.png') as im:
            im.convert('RGB').save(web/f'{name}.webp',quality=88,method=6)
            views.append({'url':f'assets/website/{name}.webp','alt':f'Indic NotePad actual Windows desktop: {caption}','caption':caption,'width':im.width,'height':im.height})
    # Original code-native share-card composition, using an unmodified actual app
    # capture as the illustration. No mockup is presented as application evidence.
    canvas=Image.new('RGB',(1200,630),'#0c141f');d=ImageDraw.Draw(canvas)
    bold=ImageFont.truetype('C:/Windows/Fonts/segoeuib.ttf',49);normal=ImageFont.truetype('C:/Windows/Fonts/segoeui.ttf',23);small=ImageFont.truetype('C:/Windows/Fonts/segoeui.ttf',18)
    icon=Image.open(ROOT/'assets/icons/icon-512.png').resize((100,100),Image.Resampling.LANCZOS);canvas.paste(icon,(44,45),icon)
    d.text((164,53),'Indic NotePad',font=bold,fill='#e0e8f4');d.text((166,114),'Your words, in focus.',font=normal,fill='#9db0c9')
    capture=Image.open(ROOT/'assets/screenshots/desktop/dark-reading.png').convert('RGB');capture.thumbnail((1080,400),Image.Resampling.LANCZOS);x=(1200-capture.width)//2;canvas.paste(capture,(x,185))
    d.text((48,591),'Native Windows editor  ·  MIT open source',font=small,fill='#65dabe');d.text((918,591),'indicstudio.com',font=small,fill='#9db0c9');canvas.save(web/'social-card.png',optimize=True);canvas.save(ROOT/'assets/banners/social-card.png',optimize=True)
    receipt=json.loads((ROOT/'local-work/native/build-windows-x64.json').read_text(encoding='utf-8'))
    downloads=[]
    for artifact in receipt['artifacts']:
        portable=artifact['file'].endswith('.zip')
        downloads.append({'label':'Download portable ZIP' if portable else 'Download Windows installer','url':f'https://github.com/ranjanlive/indic-notepad/releases/download/v{VERSION}/'+artifact['file'],'size':f'{artifact["bytes"]/1024:.0f} KiB','sha256':artifact['sha256'],'architecture':'x64','format':'zip' if portable else 'exe'})
    m={'$schema':'../schemas/product.schema.json','schema_version':1,'slug':'indic-notepad','type':'tools','title':'Indic NotePad','tagline':'Your words, in focus.','short_description':'A native, offline Windows text editor for notes, Markdown and code. Useful tabs, careful Unicode files, bounded search and local recovery—without an embedded browser.','full_description':['A little space for your thoughts. Indic NotePad brings clear native Windows editing to everyday notes, configuration and source files, with a quiet dark or light interface and no application account or upload service.','Work across tabs, use familiar editing shortcuts, highlight common source formats and find exactly what you need with case, whole-word or bounded PCRE2 regex search. Replace All confirms its count and groups the edits into one undo action. Replacement text is literal, including in regex mode.','Read UTF-8 or BOM-marked UTF-16 LE/BE, preserve existing line endings, choose an output encoding and explicitly convert EOLs. Saving checks the original file identity and content fingerprint before writing/flushing a temporary sibling and replacing the original on supported local Windows filesystems.','Local recovery keeps separate snapshots of dirty buffers. Turn history/recovery features on or off, clear stored lists, use a portable profile, or keep your default Windows application-data profile. Recovery is plaintext local data, not encryption or a substitute for backups.','Open the optional folder explorer or simplified native Markdown reader when useful. Focus mode removes optional chrome; themes and the font picker help make the space your own. No web runtime, interpreters, language-server bundles or persistent service is required.','This unsigned Windows x64 beta is a scoped first release. Editing is limited to 32 MiB per file; oversized files offer only the first 4 MiB in a read-only preview. Full virtual large-file navigation, split editing, printing, folder search and diff are future work. Independent clean-machine Windows 10/11, full assistive-technology/IME/RTL and cold-start testing remain pending.'],'status':'draft','category':'Productivity','tags':['Text editor','Windows','Native','Offline','Markdown','Open source'],'accent':'#1362BE','tint':'#EAF3FF','icon_url':'assets/website/icon.webp','social_image_url':'assets/website/social-card.png','version':VERSION,'platforms':[{'os':'windows','requirements':'Windows 10/11 x64 target. Native Win32, static MSVC runtime; no WebView, Java or Python required to run. Unsigned beta. Tested on the recorded Windows 11 host and Windows 2025 CI; clean-machine Windows 10/11 coverage is pending.','architectures':['x64'],'version':VERSION,'downloads':downloads}],'source_code_url':'https://github.com/ranjanlive/indic-notepad','website_url':f'https://github.com/ranjanlive/indic-notepad/releases/tag/v{VERSION}','support_email':'support@indicstudio.com','price':{'amount':0,'currency':'INR','label':'Free · MIT open source'},'features':[{'title':'A native space for notes and code','description':'C++20, Win32 and Scintilla, with tabs, undo/redo, common syntax modes, line numbers, wrap, zoom and keyboard shortcuts.'},{'title':'Careful Unicode file handling','description':'Strict UTF-8 and BOM-marked UTF-16 LE/BE, explicit save encoding/EOL controls and conflict-aware local replacement.'},{'title':'Find with clear boundaries','description':'Case, Unicode-aware whole word and PCRE2 regex, background cancellation and resource limits; confirmed literal replacement.'},{'title':'Local recovery, your control','description':'Debounced snapshots separate from original files, recovery consent, recent-file clearing and separate/portable profiles.'},{'title':'Choose your workspace','description':'Dark, light or system theme, focus mode, font selection, command palette, optional explorer and native Markdown reading pane.'},{'title':'Small distribution, honest scope','description':'Windows portable ZIP and per-user installer under 1 MiB each in this beta; no embedded browser or application service. Measured performance is published with its limits.'}],'screenshots_url':{'android_view':[],'tablet_view':[],'desktop_view':views},'change_logs':[{'version':VERSION,'date':DATE,'title':'First native Windows beta','changes':['Multi-tab Unicode text editing with native Scintilla syntax modes.','Bounded search/replace, local recovery and conflict-aware file saving.','Dark/light/system themes, focus mode, command palette and optional native panes.','Windows x64 portable ZIP and per-user installer; MIT source and unsigned beta.']}],'faqs':[{'question':'Does it require a browser runtime or account?','answer':'No. The application is native C++/Win32 with Windows system controls and statically linked editor/search libraries. It has no application account, telemetry, cloud upload or background service.'},{'question':'Can it edit a 1 GB log?','answer':'No. Editable documents are limited to 32 MiB. Larger files may be opened as a clearly labeled read-only preview of the first 4 MiB. The full file is not loaded or searchable, and that preview cannot overwrite the original.'},{'question':'Are recovery buffers private?','answer':'They stay in the selected local profile, but are plaintext and can contain sensitive text and paths. Use the recovery/history controls and consider backups or synchronization affecting that folder. Uninstall retains personal recovery/settings.'},{'question':'Is this a stable, signed release?','answer':'It is an unsigned public beta. Native build and control tests, host package checks and limited user-input smoke are recorded. Clean Windows 10/11 installs, broader accessibility/IME/RTL and cold-start/typing benchmarks remain pending.'},{'question':'How small and fast is it?','answer':'The current Windows portable ZIP and installer are each under 1 MiB. Five warm, visible samples on the recorded host measured about 143 ms p50 to input-idle and 22 MiB private working set for one 10 KiB note. The report distinguishes working set/private bytes, actual idle CPU and unmeasured cold/typing performance.'},{'question':'Can I modify and redistribute it?','answer':'The application source is MIT licensed. Scintilla/Lexilla and PCRE2 retain their bundled notices. IndicStudio names and marks do not imply endorsement of modified distributions.'}],'privacy_summary':'Local text processing with no application account, analytics or uploads. Optional local plaintext recovery and recent-file history are under your control.','release_note':'Unsigned Windows x64 beta. Full virtual large-file viewing, split editing and printing are deferred. Review the published tests/limits and SHA-256 values; do not treat warm host measurements as cold-start or clean-machine certification.','updated':DATE,'seo':{'title':'Indic NotePad — Native Offline Text Editor for Windows','description':'Write notes, Markdown and code in a native Windows text editor. Tabs, syntax highlighting, bounded find/replace, local recovery and themes. Free MIT open-source beta.','noindex':True}}
    dump(ROOT/'docs/website/metadata.json',m)
    sections=[('files','Text you choose to open',['Indic NotePad reads files you select through native dialogs, command-line paths, drag/drop or the optional folder explorer. Text is kept in local editing buffers. Supported Unicode encodings are validated; the application does not execute scripts, macros or opened content.'],[]),('saving','Saving and temporary files',['Save writes/flushed a temporary sibling before replacing or committing the destination. File fingerprints include identity, size, modification time and a SHA-256 content checksum. Temporary files normally disappear on completion; a crash or filesystem failure may leave local temporary data. Original documents are not automatically timer-saved.'],[]),('profile','Settings, history and recovery',['The default profile is %LOCALAPPDATA%\\IndicStudio\\IndicNotePad. Portable mode uses an adjacent data folder; --data-dir chooses another local profile. Settings include appearance and editor preferences. Optional recent history stores local file paths. The app uses a profile lock to prevent simultaneous state writers.','Recovery snapshots can contain unsaved text, document paths, encoding, cursor state and original-file fingerprints. They are stored locally in a checksummed, size-bounded file. This checksum detects corruption; it does not encrypt the data. Anyone with appropriate access to the profile or its backups may be able to read it.'],['Recovery and clean-tab restoration are settings you control. Recovery restoration requires consent when dirty snapshots exist.','Clear recent file history removes the remembered list; disabling history stops persisting that list.','Disabling recovery stops new snapshots and retains existing ones until you separately confirm clearing or remove the profile.','A cancelled recovery prompt keeps previous buffers for later and pauses overwriting them during that session.']),('network','No application cloud or telemetry',['The app has no account system, advertising, analytics, remote fonts, text upload service or automatic update checks. Markdown reading uses native Windows text controls and does not load remote images, execute scripts or render arbitrary HTML.','The operating system, antivirus, shell file dialogs, cloud-synced filesystem providers and any backup software have independent behavior and policies. The application does not control them. The website, GitHub repository and release downloads are separate services with their own hosting/logging policies.'],[]),('retention','Retention, deletion and uninstall',['You control original documents and the local profile. Save/discard/clear actions update recovery as described in the offline help; snapshots are not an archival backup. Uninstall removes the application and its own shortcut/registry record but retains documents, settings and recovery data.','To erase local recovery/settings completely, close all instances and remove the selected profile folder through your operating system. Consider copies retained by backups, synchronizers or other users. IndicStudio has no application server-side copy to erase.'],[]),('permissions','Access and permissions',['The app runs with ordinary user privileges and accesses user-selected files and the local profile. It requests no camera, microphone, contacts or location permission. The per-user installer creates its application folder, one Start menu shortcut and an uninstall entry; it does not silently make itself the default editor or install a background service.'],[]),('scope','Version and scope',['This notice describes 0.1.0-beta.1 for Windows x64. Future network/data-collection features require an updated notice. Development benchmarks/tests are separate from normal app use and use synthetic files and isolated local profiles.'],[]),('contact','Contact',['For product or privacy questions, contact support@indicstudio.com. Do not include private text, recovery files, credentials or personal documents in public GitHub issues.'],[])]
    dump(ROOT/'docs/website/privacy_content.json',{'$schema':'../schemas/privacy.schema.json','schema_version':1,'title':'Privacy notice for Indic NotePad','effective_date':DATE,'summary':'Indic NotePad edits text locally. It has no application account, analytics, text-upload service or background cloud storage. Optional plaintext recovery and recent paths stay in your chosen local profile.','sections':[{'id':i,'title':t,'paragraphs':p,'bullets':b} for i,t,p,b in sections]})
    dump(ROOT/'docs/store/store-listing.json',{'status':'beta','title':'Indic NotePad','tagline':m['tagline'],'short_description':m['short_description'],'description':m['full_description'],'platforms':['windows-x64'],'version':VERSION,'license':'MIT','availability':'Unsigned public GitHub beta; no Microsoft Store submission is claimed.','support':'support@indicstudio.com','privacy_url':'https://indicstudio.com/tools/indic-notepad/privacy/'})
if __name__=='__main__':main()
